compile.workshop:
variables {
    global:
        0: g
        1: h
    player:
        0: p
        1: q
}

//Optimize for size enabled
rule ("size literals") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, p, Null);
        Set Player Variable(Event Player, q, Null);
        Set Global Variable(g, Null);
        Set Global Variable(g, Add(Left, Right));
        Set Global Variable(g, Array(Null, False, True, Add(Left, Right), -1, Vector(-1.5, 2, -3)));
        Modify Global Variable(g, Add, True);
        Modify Global Variable(g, Subtract, True);
        Modify Global Variable(g, Append To Array, Null);
        Set Global Variable At Index(h, False, Null);
        Modify Global Variable At Index(h, True, Add, True);
        Set Player Variable At Index(Event Player, p, True, Null);
        For Global Variable(h, 0, 3, True);
            Modify Global Variable(g, Add, 2);
        End;
        If(And(And(Compare(Global.g, >, Null), Compare(Global.h, >=, 1)), Compare(Global.g, !=, Null)));
            Set Global Variable(g, If-Then-Else((Event Player).p, 1, Null));
        End;
        Wait(False, Ignore Condition);
    }
}

